import {
  useMutation,
  useQuery,
  useQueryClient,
  useMutation as useSettingsMutation,
  useQuery as useSettingsQuery,
} from '@tanstack/react-query';
import type React from 'react';
import { useMemo, useState } from 'react';
import { settingsApi } from '@/api/settings';
import type { SubmissionItem } from '@/api/submissions';
import { submissionsApi } from '@/api/submissions';
import { SubmissionDetailModal } from './submission-detail-modal';
import {
  type SubmissionsConfig,
  SubmissionsConfigModal,
} from './submissions-config-modal';
import { SubmissionsTable } from './submissions-table';

export const SubmissionsTab: React.FC = () => {
  const queryClient = useQueryClient();
  const [currentPage, setCurrentPage] = useState(1);
  const [perPage, setPerPage] = useState(50);

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ['submissions', { paged: currentPage, per_page: perPage }],
    queryFn: () =>
      submissionsApi.list({ paged: currentPage, per_page: perPage }),
  });

  const items: SubmissionItem[] = data?.items || [];
  const totalPages = data?.total_pages || 0;
  const total = data?.total || 0;

  const [detail, setDetail] = useState<SubmissionItem | null>(null);
  const [showConfig, setShowConfig] = useState(false);

  const { data: settingsData } = useSettingsQuery({
    queryKey: ['settings'],
    queryFn: () => settingsApi.get(),
  });

  const currentConfig: SubmissionsConfig = useMemo(() => {
    const subs = (settingsData?.settings as any)?.submissions || {};
    return {
      // Webhook
      webhook_enabled: !!subs.webhook_enabled,
      webhook_url: subs.webhook_url || '',
      webhook_secret: subs.webhook_secret || '',
      webhook_secret_key: subs.webhook_secret_key || '',
      // Server酱
      serverchan_enabled: !!subs.serverchan_enabled,
      serverchan_sendkey: subs.serverchan_sendkey || '',
      thankyou_url: subs.thankyou_url || '',
      // wp_mail
      email_enabled: !!subs.email_enabled,
      email_to: subs.email_to || '',
      email_subject: subs.email_subject || '',
    } as SubmissionsConfig;
  }, [settingsData?.settings]);

  const saveSettingsMutation = useSettingsMutation({
    mutationFn: (nextCfg: SubmissionsConfig) => {
      const base = settingsData?.settings || {};
      const next = { ...base, submissions: { ...nextCfg } } as any;
      return settingsApi.update(next);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['settings'] });
      setShowConfig(false);
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => submissionsApi.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['submissions'] });
    },
  });

  const handleDelete = async (id: number) => {
    if (!confirm('确定要删除这条提交吗？')) {
      return;
    }
    await deleteMutation.mutateAsync(id);
  };

  return (
    <div className="rounded-xl border border-gray-200 bg-white p-6 shadow-sm">
      <div className="mb-4 flex items-center justify-between">
        <h2 className="font-semibold text-gray-900 text-lg">表单提交</h2>
        <div className="space-x-2">
          <button
            className="rounded-md bg-gray-200 px-3 py-1.5 text-gray-700 text-sm hover:bg-gray-300"
            onClick={() => setShowConfig(true)}
            title="配置提交安全和行为"
            type="button"
          >
            ⚙️ 设置
          </button>
          <button
            className="rounded-md bg-blue-600 px-3 py-1.5 text-sm text-white hover:bg-blue-700"
            onClick={() => submissionsApi.exportCsv()}
            type="button"
          >
            导出 CSV
          </button>
          <button
            className="rounded-md bg-gray-100 px-3 py-1.5 text-gray-700 text-sm hover:bg-gray-200"
            onClick={() => refetch()}
            type="button"
          >
            刷新
          </button>
        </div>
      </div>

      {isLoading && <div className="text-gray-500">加载中...</div>}
      {error && (
        <div className="text-red-600">
          加载失败：{String((error as any)?.message || '')}
        </div>
      )}

      {showConfig && (
        <SubmissionsConfigModal
          initial={currentConfig}
          onClose={() => setShowConfig(false)}
          onSave={(next) => saveSettingsMutation.mutate(next)}
          open
          saving={saveSettingsMutation.isPending}
        />
      )}

      {!(isLoading || error) && items.length === 0 && (
        <div className="text-gray-500">暂无提交</div>
      )}

      {!(isLoading || error) && items.length > 0 && (
        <>
          <SubmissionsTable
            deleting={deleteMutation.isPending}
            items={items}
            onDelete={(id) => handleDelete(id)}
            onView={(it) => setDetail(it)}
          />

          {/* 分页控制 */}
          <div className="mt-4 flex items-center justify-between border-gray-200 border-t pt-4">
            <div className="text-gray-600 text-sm">
              共 {total} 条记录，当前第 {currentPage} / {totalPages} 页
            </div>
            <div className="flex items-center gap-2">
              <button
                className="rounded-md border border-gray-300 bg-white px-3 py-1.5 text-gray-700 text-sm hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
                disabled={currentPage <= 1}
                onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                type="button"
              >
                上一页
              </button>
              <span className="text-gray-700 text-sm">第 {currentPage} 页</span>
              <button
                className="rounded-md border border-gray-300 bg-white px-3 py-1.5 text-gray-700 text-sm hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
                disabled={currentPage >= totalPages}
                onClick={() =>
                  setCurrentPage((p) => Math.min(totalPages, p + 1))
                }
                type="button"
              >
                下一页
              </button>
              <select
                className="rounded-md border border-gray-300 bg-white px-2 py-1.5 text-gray-700 text-sm"
                onChange={(e) => {
                  setPerPage(Number(e.target.value));
                  setCurrentPage(1); // 重置到第一页
                }}
                value={perPage}
              >
                <option value={10}>10 条/页</option>
                <option value={25}>25 条/页</option>
                <option value={50}>50 条/页</option>
                <option value={100}>100 条/页</option>
              </select>
            </div>
          </div>
        </>
      )}

      {detail && (
        <SubmissionDetailModal
          item={detail}
          onClose={() => setDetail(null)}
          open
        />
      )}
    </div>
  );
};
