import type React from 'react';
import { useEffect, useState } from 'react';

export interface SubmissionsConfig {
  serverchan_enabled: boolean;
  serverchan_sendkey: string;
  thankyou_url: string;
  // Webhook 通知
  webhook_enabled?: boolean;
  webhook_url?: string;
  webhook_secret?: string;
  webhook_secret_key?: string;
  // Sales email via wp_mail
  email_enabled?: boolean;
  email_to?: string;
  email_subject?: string;
}

interface Props {
  open: boolean;
  initial: SubmissionsConfig;
  saving?: boolean;
  onClose: () => void;
  onSave: (next: SubmissionsConfig) => void;
}

export const SubmissionsConfigModal: React.FC<Props> = ({
  open,
  initial,
  saving,
  onClose,
  onSave,
}) => {
  const [draft, setDraft] = useState<SubmissionsConfig>(initial);

  useEffect(() => {
    setDraft(initial);
  }, [initial]);

  if (!open) {
    return null;
  }

  return (
    <div
      aria-modal="true"
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
      role="dialog"
      tabIndex={-1}
    >
      <button
        aria-label="关闭"
        className="absolute inset-0 z-0 h-full w-full bg-transparent"
        onClick={onClose}
        type="button"
      />
      <div className="relative z-10 flex max-h-[90vh] w-full max-w-3xl flex-col rounded-lg bg-white shadow-2xl">
        <div className="flex flex-shrink-0 items-center justify-between border-gray-200 border-b px-6 py-4">
          <h3 className="font-semibold text-gray-900 text-lg">提交设置</h3>
          <button
            className="rounded-md bg-gray-100 px-3 py-1.5 text-gray-700 text-sm hover:bg-gray-200"
            onClick={onClose}
            type="button"
          >
            关闭
          </button>
        </div>

        <div className="min-h-0 flex-1 space-y-6 overflow-y-auto px-6 py-5">
          <section>
            <div className="mb-2 font-medium text-gray-900">
              Webhook 通知（可选）
            </div>
            <label className="mb-2 flex items-center gap-2 text-gray-700 text-sm">
              <input
                checked={!!draft.webhook_enabled}
                className="h-4 w-4"
                onChange={(e) =>
                  setDraft({ ...draft, webhook_enabled: e.target.checked })
                }
                type="checkbox"
              />
              启用 Webhook
            </label>
            <div className="text-gray-600 text-sm">
              表单提交后，以 JSON 格式 POST 到指定 URL。可对接 Zapier、Make、n8n
              或自建系统。
            </div>
            <div className="mt-2 grid grid-cols-1 gap-3 md:grid-cols-2">
              <div className="md:col-span-2">
                <div className="mb-1 text-gray-700 text-sm">Webhook URL</div>
                <input
                  className="w-full rounded border border-gray-300 px-3 py-2 text-sm"
                  onChange={(e) =>
                    setDraft({ ...draft, webhook_url: e.target.value })
                  }
                  placeholder="https://hooks.zapier.com/..."
                  type="url"
                  value={draft.webhook_url || ''}
                />
              </div>
              <div>
                <div className="mb-1 text-gray-700 text-sm">
                  验证 Header 名称（可选）
                </div>
                <input
                  className="w-full rounded border border-gray-300 px-3 py-2 text-sm"
                  onChange={(e) =>
                    setDraft({ ...draft, webhook_secret_key: e.target.value })
                  }
                  placeholder="X-Webhook-Secret"
                  type="text"
                  value={draft.webhook_secret_key || ''}
                />
              </div>
              <div>
                <div className="mb-1 text-gray-700 text-sm">
                  验证 Header 值（可选）
                </div>
                <input
                  className="w-full rounded border border-gray-300 px-3 py-2 text-sm"
                  onChange={(e) =>
                    setDraft({ ...draft, webhook_secret: e.target.value })
                  }
                  placeholder="your-secret-token"
                  type="password"
                  value={draft.webhook_secret || ''}
                />
              </div>
            </div>
          </section>

          <section>
            <div className="mb-2 font-medium text-gray-900">
              Server酱 通知（可选）
            </div>
            <label className="mb-2 flex items-center gap-2 text-gray-700 text-sm">
              <input
                checked={!!draft.serverchan_enabled}
                className="h-4 w-4"
                onChange={(e) =>
                  setDraft({ ...draft, serverchan_enabled: e.target.checked })
                }
                type="checkbox"
              />
              启用 Server酱 推送
            </label>
            <div className="text-gray-600 text-sm">
              开启后，我们会请求
              <code>
                {' '}
                https://sctapi.ftqq.com/&lt;SENDKEY&gt;.send?title=...&amp;desp=...{' '}
              </code>
            </div>
            <div className="mt-2 grid grid-cols-1 gap-3 md:grid-cols-2">
              <div className="md:col-span-2">
                <div className="mb-1 text-gray-700 text-sm">SendKey</div>
                <input
                  className="w-full rounded border border-gray-300 px-3 py-2 text-sm"
                  onChange={(e) =>
                    setDraft({ ...draft, serverchan_sendkey: e.target.value })
                  }
                  placeholder="SCTxxxxxxxxxxxxxxxxxxxx"
                  type="text"
                  value={draft.serverchan_sendkey}
                />
              </div>
            </div>
          </section>

          <section>
            <div className="mb-2 font-medium text-gray-900">
              业务员邮件通知（wp_mail）
            </div>
            <label className="mb-2 flex items-center gap-2 text-gray-700 text-sm">
              <input
                checked={!!draft.email_enabled}
                className="h-4 w-4"
                onChange={(e) =>
                  setDraft({ ...draft, email_enabled: e.target.checked })
                }
                type="checkbox"
              />
              启用 wp_mail 发送
            </label>
            <div className="text-gray-600 text-sm">
              未配置收件人时，将回退到站点管理员邮箱。支持英文逗号或分号分隔多个收件人。
            </div>
            <div className="mt-2 grid grid-cols-1 gap-3 md:grid-cols-2">
              <div className="md:col-span-2">
                <div className="mb-1 text-gray-700 text-sm">收件人邮箱</div>
                <input
                  className="w-full rounded border border-gray-300 px-3 py-2 text-sm"
                  onChange={(e) =>
                    setDraft({ ...draft, email_to: e.target.value })
                  }
                  placeholder="sales@example.com; support@example.com"
                  type="text"
                  value={draft.email_to || ''}
                />
              </div>
              <div className="md:col-span-2">
                <div className="mb-1 text-gray-700 text-sm">
                  邮件标题（发送时会自动追加 #ID）
                </div>
                <input
                  className="w-full rounded border border-gray-300 px-3 py-2 text-sm"
                  onChange={(e) =>
                    setDraft({ ...draft, email_subject: e.target.value })
                  }
                  placeholder="New inquiry from website"
                  type="text"
                  value={draft.email_subject || ''}
                />
              </div>
            </div>
          </section>

          {null}

          <section>
            <div className="mb-2 font-medium text-gray-900">
              提交成功跳转（可选）
            </div>
            <div className="text-gray-600 text-sm">
              若配置，HTMX 请求将使用 <code>HX-Redirect</code> 跳转到此感谢页。
            </div>
            <input
              className="mt-2 w-full rounded border border-gray-300 px-3 py-2 text-sm"
              onChange={(e) =>
                setDraft({ ...draft, thankyou_url: e.target.value })
              }
              placeholder="https://example.com/thank-you"
              type="url"
              value={draft.thankyou_url}
            />
          </section>
        </div>

        <div className="flex flex-shrink-0 justify-end gap-2 border-gray-200 border-t px-6 py-4">
          <button
            className="rounded-md bg-gray-100 px-4 py-2 text-gray-700 text-sm hover:bg-gray-200"
            onClick={onClose}
            type="button"
          >
            取消
          </button>
          <button
            className="rounded-md bg-blue-600 px-4 py-2 text-sm text-white hover:bg-blue-700 disabled:opacity-50"
            disabled={!!saving}
            onClick={() => onSave(draft)}
            type="button"
          >
            保存
          </button>
        </div>
      </div>
    </div>
  );
};
