import type React from 'react';
import type { SubmissionItem } from '@/api/submissions';

interface Props {
  items: SubmissionItem[];
  onView: (item: SubmissionItem) => void;
  onDelete: (id: number) => void;
  deleting?: boolean;
}

export const SubmissionsTable: React.FC<Props> = ({
  items,
  onView,
  onDelete,
  deleting,
}) => {
  if (!items.length) {
    return null;
  }
  return (
    <div className="overflow-x-auto">
      <table className="min-w-full divide-y divide-gray-200">
        <thead className="bg-gray-50">
          <tr>
            <th className="px-4 py-2 text-left font-medium text-gray-500 text-xs uppercase tracking-wider">
              时间
            </th>
            <th className="px-4 py-2 text-left font-medium text-gray-500 text-xs uppercase tracking-wider">
              来源网页
            </th>
            <th className="px-4 py-2 text-left font-medium text-gray-500 text-xs uppercase tracking-wider">
              位置
            </th>
            <th className="px-4 py-2 text-left font-medium text-gray-500 text-xs uppercase tracking-wider">
              操作
            </th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-200 bg-white">
          {items.map((item) => (
            <tr className="align-top" key={item.id}>
              <td className="whitespace-nowrap px-4 py-2 text-gray-700 text-sm">
                {new Date(item.date.replace(' ', 'T')).toLocaleString()}
              </td>
              <td className="max-w-xl px-4 py-2 text-gray-700 text-sm">
                {item.source_url ? (
                  <a
                    className="line-clamp-2 break-all text-blue-600 hover:underline"
                    href={item.source_url}
                    rel="noreferrer"
                    target="_blank"
                    title={item.source_url}
                  >
                    {item.source_url}
                  </a>
                ) : (
                  <span className="text-gray-400">未知</span>
                )}
              </td>
              <td className="px-4 py-2 text-gray-700">
                <span className="text-xs leading-5">
                  {item.location || item.country || '未知'}
                </span>
              </td>
              <td className="whitespace-nowrap px-4 py-2 text-sm">
                <div className="flex items-center gap-2">
                  <button
                    className="rounded-md bg-gray-800 px-2.5 py-1 text-white hover:bg-black"
                    onClick={() => onView(item)}
                    type="button"
                  >
                    查看详情
                  </button>
                  <button
                    className="rounded-md bg-red-600 px-2.5 py-1 text-white hover:bg-red-700 disabled:opacity-50"
                    disabled={deleting}
                    onClick={() => onDelete(item.id)}
                    type="button"
                  >
                    删除
                  </button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};
