import type React from 'react';
import type { SubmissionItem } from '@/api/submissions';

interface Props {
  open: boolean;
  item: SubmissionItem | null;
  onClose: () => void;
}

// 格式化文件大小
const formatFileSize = (bytes: number): string => {
  if (bytes === 0) {
    return '0 B';
  }
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${(bytes / k ** i).toFixed(1)} ${sizes[i]}`;
};

// 辅助函数：渲染不同类型的值
const renderValue = (key: string, value: any): React.ReactNode => {
  if (value === null || value === undefined) {
    return <span className="text-gray-400 italic">空</span>;
  }
  if (typeof value === 'boolean') {
    return (
      <span className={value ? 'text-green-600' : 'text-red-600'}>
        {value ? '是' : '否'}
      </span>
    );
  }

  // 特殊处理附件字段
  if (key === 'attachments' && Array.isArray(value)) {
    return (
      <div className="space-y-1.5">
        {value.map((att, idx) => {
          const url = att?.url || '';
          const filename = att?.filename || att?.name || '';
          const size = att?.size || 0;

          if (!url) {
            return null;
          }

          return (
            <div className="flex items-center gap-2" key={url || idx}>
              <span className="text-lg">📎</span>
              <a
                className="break-all text-blue-600 hover:underline"
                href={url}
                rel="noreferrer"
                target="_blank"
              >
                {filename || url}
              </a>
              {size > 0 && (
                <span className="whitespace-nowrap text-gray-500 text-xs">
                  ({formatFileSize(size)})
                </span>
              )}
            </div>
          );
        })}
      </div>
    );
  }

  if (typeof value === 'object') {
    // 对象或数组：显示为紧凑的 JSON
    return (
      <pre className="whitespace-pre-wrap break-all text-xs">
        {JSON.stringify(value, null, 2)}
      </pre>
    );
  }
  // 字符串、数字等
  return <span className="break-all">{String(value)}</span>;
};

export const SubmissionDetailModal: React.FC<Props> = ({
  open,
  item,
  onClose,
}) => {
  if (!(open && item)) {
    return null;
  }

  // Keyboard handling can be added globally if needed

  return (
    <div
      aria-modal="true"
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
      role="dialog"
      tabIndex={-1}
    >
      {/* clickable backdrop button for a11y */}
      <button
        aria-label="关闭"
        className="absolute inset-0 z-0 h-full w-full bg-transparent"
        onClick={onClose}
        type="button"
      />
      <div className="relative z-10 max-h-[85vh] w-full max-w-3xl overflow-auto rounded-lg bg-white p-6 shadow-2xl">
        <div className="mb-4 flex items-center justify-between">
          <h3 className="font-semibold text-gray-900 text-lg">提交详情</h3>
          <button
            className="rounded-md bg-gray-100 px-3 py-1.5 text-gray-700 text-sm hover:bg-gray-200"
            onClick={onClose}
            type="button"
          >
            关闭
          </button>
        </div>
        <div className="space-y-2 text-gray-700 text-sm">
          <div>
            时间：{new Date(item.date.replace(' ', 'T')).toLocaleString()}
          </div>
          <div>
            来源网页：{' '}
            {item.source_url ? (
              <a
                className="break-all text-blue-600 hover:underline"
                href={item.source_url}
                rel="noreferrer"
                target="_blank"
              >
                {item.source_url}
              </a>
            ) : (
              '未知'
            )}
          </div>
          <div>IP：{item.ip || (item.context?.ip as string) || '未知'}</div>
          <div>
            位置：
            <span className="text-xs leading-5">
              {item.location || item.country || '未知'}
            </span>
          </div>
        </div>
        <div className="mt-4">
          <div className="mb-2 font-medium text-gray-900 text-sm">提交数据</div>
          <div className="max-h-[50vh] overflow-auto rounded border border-gray-200">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="sticky top-0 bg-gray-50">
                <tr>
                  <th className="px-3 py-2 text-left font-medium text-gray-500 text-xs uppercase">
                    字段名
                  </th>
                  <th className="px-3 py-2 text-left font-medium text-gray-500 text-xs uppercase">
                    值
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200 bg-white">
                {Object.entries(item.payload).map(([key, value]) => (
                  <tr className="hover:bg-gray-50" key={key}>
                    <td className="whitespace-nowrap px-3 py-2 align-top font-medium text-gray-900 text-sm">
                      {key}
                    </td>
                    <td className="px-3 py-2 text-gray-700 text-sm">
                      {renderValue(key, value)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};
